const BASE_URL = "{{BASE_URL}}";
const API_KEY = "{{API_KEY}}";
const jobId = "job_3f9c2a7e5b8d4c1fa0e6b2d9c7f41a58";

const TERMINAL = new Set(["succeeded", "failed", "cancelled"]);
let job;
do {
  const resp = await fetch(`${BASE_URL}/v1/jobs/${jobId}`, {
    headers: { Authorization: `Bearer ${API_KEY}` },
  });
  if (!resp.ok) throw new Error(JSON.stringify(await resp.json()));
  job = await resp.json();
  console.log(job.status, job.queue_position);
  if (!TERMINAL.has(job.status)) await new Promise((r) => setTimeout(r, 2000));
} while (!TERMINAL.has(job.status));
